    'B3':{(r,c) for r,c in ALL if c>=r or (c>=5 and r+c>=10)}}
Ev={'E1':{(r,c) for r,c in ALL if c<=r},
    'E2':{(r,c) for r,c in ALL if c<=r or (r>=5 and c>r)}}
Fv={'F1':{(r,c) for r,c in ALL if r>=5},
    'F2':{(r,c) for r,c in ALL if r>=5 and c>r}}
tgt={}
for r,c in ALL: tgt[(r,c)]='p' if (r<=4 and c<=8-r) else ('o' if r+c>=9 else 'w')
