{"code": "def get_target():
    a=current_frame.ascii.split('\n')
    return [[a[3+r][3+c] for c in range(10)] for r in range(10)]
def cellsets():
    return {name:[(r,c) for r in range(10) for c in range(10) if f(r,c)] for name,f in REG.items()}
def solve(maxdepth=6):
    tgt=get_target()
    CS=cellsets()
    cols=sorted(set(tgt[r][c] for r in range(10) for c in range(10)))
    start=[[tgt[r][c] for c in range(10)] for r in range(10)]
    best=None
    def key(g): return ''.join(''.join(row) for row in g)
    def done(g): return all(g[r][c] in '?W' for r in range(10) for c in range(10))
    def dfs(g,path,seen):
        nonlocal best
        if done(g):
            if best is None or len(path)<len(best): best=list(path)
            return
        if len(path)>=maxdepth or best is not None and len(path)+1>=len(best): return
        cands=[]
        for name,S in CS.items():
            for col in cols:
                spec=[(r,c) for r,c in S if g[r][c] not in '?']
                if not spec: continue
                if all(g[r][c]==col for r,c in spec):
                    cands.append((len(spec),name,col))
        cands.sort(reverse=True)
        for n,name,col in cands:
            g2=[row[:] for row in g]
            for (r,c) in CS[name]: g2[r][c]='?'
            k=key(g2)
            if k in seen: continue
            seen.add(k)
            path.append((name,col))
            dfs(g2,path,seen)
            path.pop()
    dfs(start,[],{key(start)})
    return best,[tgt[r][c] for r in range(10) for c in range(10)]
sol,_=solve(6)
print('solution (reverse order):',sol)
"}

