    FREE=frozenset(k for k,v in M.items() if v!='#')
    Lg=[k for k,v in M.items() if v=='S']; sm=[k for k,v in M.items() if v=='b']
    if len(Lg)!=2 or len(sm)!=3: return ('badread',Lg,sm)
    L0,R0=(Lg[0],Lg[1]) if Lg[0][1]<Lg[1][1] else (Lg[1],Lg[0])
    s0=tuple(sorted(sm))
    MOV={'UP':(-1,0),'DOWN':(1,0),'LEFT':(0,-1),'RIGHT':(0,1)}
    start=(L0,R0,s0,'B')
    from collections import deque
    seen={start:None}; q=deque([start]); t0=time.time(); goal=[]
    while q:
        if len(seen)>maxn or time.time()-t0>tlimit: return ('capped',len(seen))
        st=q.popleft()
        L,R,s,act=st
        occ=frozenset([L,R])+frozenset(s)
        for m,(dx,dy) in MOV.items():
            if act=='B':
                Ld=(L[0]+dx,L[1]+dy); Rd=(R[0]-0*dx,R[1]-dy)
                if Ld==R and Rd==L and Ld in FREE and Rd in FREE:
                    goal.append((st,m)); continue
                nL=Ld if (Ld in FREE and Ld not in occ-{L}) else L
                nR=Rd if (Rd in FREE and Rd not in occ-{R}) else R
                if (nL,nR)==(L,R): continue
                ns=(nL,nR,s,'B')
            else:
                k=act; p=s[k]; d=(dx,dy)
                Pd=(p[0]+d[0],p[1]+d[1])
                if Pd in FREE and Pd not in occ-{p}:
                    nl=list(s); nl[k]=Pd; ns=(L,R,tuple(nl),act)
                else: continue
            if ns not in seen: seen[ns]=(st,m); q.append(ns)
        for k,p in enumerate(s):
            if p==L or p==R: continue
            ns=(L,R,s,k)
            if ns not in seen: seen[ns]=(st,('CLICK',p)); q.append(ns)
