{"code": "def pair_solve2(L, R, parked, maxn=600000):
    M=snapw()
    FREE=set(k for k,v in M.items() if v!='#')
    for c in parked: FREE.discard(c)
    FREE.add(L); FREE.add(R)
    MOV={'UP':(-1,0),'DOWN':(1,0),'LEFT':(0,-1),'RIGHT':(0,1)}
    from collections import deque
    start=(L,R); seen={start:None}; q=deque([start]); goal=[]
    while q:
        if len(seen)>maxn: return ('capped',len(seen))
        Lp,Rp=q.popleft()
        for m,(dx,dy) in MOV.items():
            Ld=(Lp[0]+dx,Lp[1]+dy); Rd=(Rp[0]+dx,Rp[1]-dy)
            if Ld==Rp and Rd==Lp: goal.append((Lp,Rp,m)); continue
            if Ld==Rd: continue
            nL=Ld if (Ld in FREE and Ld!=Rp) else Lp
            nR=Rd if (Rd in FREE and Rd!=Lp and Rd!=nL) else Rp
            if nL==nR: continue
            ns=(nL,nR)
            if ns not in seen: seen[ns]=((Lp,Rp),m); q.append(ns)
    if not goal: return ('nogoal',len(seen))
    def pth(x):
        p=[]; cur=x
        while seen[cur] is not None:
            pp,m=seen[cur]; p.append(m); cur=pp
        return list(reversed(p))
    best=min(goal,key=lambda g:len(pth((g[0],g[1])))+1)
    return ('ok',pth((best[0],best[1]))+[best[2]],len(seen))
