        a=rem[0]
        for idx in range(1,len(rem)):
            b=rem[idx]
            if b[0]==a[0]: continue
            gen([x for x in rem[1:idx]]+[x for x in rem[idx+1:]], cur+[(a,b)])
    gen(conns,[])
    best=[]
    for ks in itertools.product(range(4),repeat=len(names)):
        kr=dict(zip(names,ks))
        for m in matchings:
            # relative offsets via BFS
            rel={names[0]:(0,0)}; frontier=[names[0]]; ok=True
            edges=[((a,i),(b,j)) for (a,i),(b,j) in m]
            while frontier and ok:
                x=frontier.pop()
                for (p,i),(q,j) in edges:
                    for u,v,ui,vj in ((x,None,None,None),):
                        pass
