                        rel[q]=(rel[p][0]+d[0], rel[p][1]+d[1]); frontier.append(q)
                    elif q==x and p not in rel:
                        d=(min(CN[(q,kr[q])][j])[0]-min(CN[(p,kr[p])][i])[0], min(CN[(q,kr[q])][j])[1]-min(CN[(p,kr[p])][i])[1])
                        rel[p]=(rel[q][0]+d[0], rel[q][1]+d[1]); frontier.append(p)
            if len(rel)!=len(names): continue
            # consistency: every edge satisfied
            for (p,i),(q,j) in edges:
                lhs=(rel[p][0]+min(CN[(p,kr[p])][i])[0], rel[p][1]+min(CN[(p,kr[p])][i])[1])
                rhs=(rel[q][0]+min(CN[(q,kr[q])][j])[0], rel[q][1]+min(CN[(q,kr[q])][j])[1])
                if lhs!=rhs: ok=False
